-- ADJUSTING - Claim Notes & Chronology
--
-- An insurance-claims working document, not a photo report: claim intake
-- header (claim/policy/insured/loss-date/adjuster fields), a damage-tags
-- checklist plus a 3-photo slot row, a running claim-notes log (contact
-- table + a status checklist), a loss-chronology snapshot table, a
-- terms-and-conditions placeholder pointing at this app's own Snippets
-- feature ("[INSERT SNIPPET]" -- see apps/web/src/lib/text-snippets.functions.ts),
-- and an adjuster/supervisor sign-off table. Unlike the numbered
-- "Pre-Built Report" family this has no cover page or merge tokens -- every
-- field here is meant to be hand-filled per claim, not auto-personalized.
INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'example-adjusting-claim-notes-chronology',
  NULL,
  NULL,
  'ADJUSTING - Claim Notes & Chronology',
  jsonb_build_object(
    'style', 'report',
    'description', 'Claim intake header, damage tags, a running claim-notes log, loss chronology, and adjuster/supervisor sign-off.',
    'html', $html$<h1>ADJUSTING - Claim Notes &amp; Chronology</h1><h2>Claim Header</h2><table><tbody><tr><th><p>Field</p></th><th><p>Value</p></th></tr><tr><td><p>Claim #</p></td><td><p></p></td></tr><tr><td><p>Policy #</p></td><td><p></p></td></tr><tr><td><p>Insured / Property</p></td><td><p></p></td></tr><tr><td><p>Loss Date</p></td><td><p></p></td></tr><tr><td><p>Cause of Loss</p></td><td><p></p></td></tr><tr><td><p>Assigned Adjuster</p></td><td><p></p></td></tr><tr><td><p>Statute of Limitations Date</p></td><td><p></p></td></tr></tbody></table><hr><h2>Damage Tags - Select all that apply</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Roof</p></li><li data-type="taskItem" data-checked="false"><p>Structure</p></li><li data-type="taskItem" data-checked="false"><p>Interior Contents</p></li><li data-type="taskItem" data-checked="false"><p>Business Interruption / ALE</p></li><li data-type="taskItem" data-checked="false"><p>Liability</p></li></ul><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'220'%20height%3D'280'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'219'%20height%3D'279'%20rx%3D'6'%20fill%3D'rgb(244%2C245%2C247)'%20stroke%3D'rgb(203%2C208%2C216)'%20stroke-dasharray%3D'5%204'%2F%3E%3Ctext%20x%3D'110'%20y%3D'132'%20font-family%3D'sans-serif'%20font-size%3D'14'%20font-weight%3D'700'%20fill%3D'rgb(107%2C114%2C128)'%20text-anchor%3D'middle'%3EPhoto%201%3C%2Ftext%3E%3Ctext%20x%3D'110'%20y%3D'152'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(156%2C163%2C175)'%20text-anchor%3D'middle'%3EClick%20to%20add%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="280" alt="Photo slot 1"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'220'%20height%3D'280'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'219'%20height%3D'279'%20rx%3D'6'%20fill%3D'rgb(244%2C245%2C247)'%20stroke%3D'rgb(203%2C208%2C216)'%20stroke-dasharray%3D'5%204'%2F